// Dropdown filter of docs/book/tutorials/index.md (generated by generate_tutorial_index.py).
// Each .zt-select filters one category; "any" (value "") leaves it open.  A card (its .zt-data
// span carries data-tags, copied onto the grid column) is shown when it has the selected tag
// of every menu that is not "any".  The selection lives in the URL hash (#dimension=1d&...),
// so the back button from a notebook returns to the same view.
document.addEventListener("DOMContentLoaded", function () {
  var filter = document.querySelector(".zt-filter");
  if (!filter) return;
  var selects = Array.prototype.slice.call(filter.querySelectorAll(".zt-select"));
  var cols = [];
  document.querySelectorAll(".zt-data").forEach(function (span) {
    var col = span.closest(".sd-col") || span.closest(".sd-card");
    col.dataset.tags = span.dataset.tags;
    cols.push(col);
  });
  var empty = document.querySelector(".zt-empty");

  function apply() {
    var want = selects.map(function (s) { return s.value; }).filter(Boolean);
    var shown = 0;
    cols.forEach(function (col) {
      var tags = col.dataset.tags.split(" ");
      var ok = want.every(function (t) { return tags.indexOf(t) >= 0; });
      col.hidden = !ok;
      if (ok) shown++;
    });
    if (empty) empty.hidden = shown > 0 || cols.length === 0;
    var parts = selects.filter(function (s) { return s.value; }).map(function (s) {
      return s.dataset.cat + "=" + encodeURIComponent(s.value.split(":")[1]);
    });
    history.replaceState(null, "", location.pathname + location.search + (parts.length ? "#" + parts.join("&") : ""));
  }

  location.hash.replace(/^#/, "").split("&").forEach(function (pair) {
    var kv = pair.split("=");
    selects.forEach(function (s) {
      if (s.dataset.cat === kv[0]) {
        var value = s.dataset.cat + ":" + decodeURIComponent(kv[1] || "");
        var option = Array.prototype.find.call(s.options, function (o) { return o.value === value && !o.disabled; });
        if (option) s.value = value;
      }
    });
  });

  selects.forEach(function (s) { s.addEventListener("change", apply); });
  var clear = filter.querySelector(".zt-clear");
  if (clear) clear.addEventListener("click", function () {
    selects.forEach(function (s) { s.value = ""; });
    apply();
  });
  apply();
});
